// Run: node tests/fixtures/verify.mjs. Tests the preview double without a browser.
import assert from 'node:assert/strict';
const memory = new Map();
globalThis.localStorage = globalThis.sessionStorage = { getItem: key => memory.get(key) ?? null, setItem: (key, value) => memory.set(key, String(value)), removeItem: key => memory.delete(key) };
globalThis.location = { search: '' };
globalThis.window = globalThis;
const fixture = await import('./firebase.js');
const { auth, db, collection, doc, getDoc, getDocs, query, where, orderBy, limit, onSnapshot, writeBatch, setDoc } = fixture;
const base = ['users', auth.currentUser.uid];
const habits = await getDocs(collection(db, ...base, 'habits'));
assert.equal(habits.size, 3);
assert.equal(habits.docs[0].data().createdAt.toDate() instanceof Date, true);
const today = new Date().toISOString().slice(0, 10);
const meals = await getDocs(query(collection(db, ...base, 'meals'), where('date', '==', today), orderBy('calories', 'desc'), limit(1)));
assert.equal(meals.size, 1);
assert.equal(meals.docs[0].data().calories, 680);
const habitProgress = await getDoc(doc(db, ...base, 'habits', 'water', 'progress', today));
assert.equal(habitProgress.data().progress, 5);
const sessions = collection(db, ...base, 'coach_sessions');
let notifications = 0;
const unsubscribe = onSnapshot(sessions, { includeMetadataChanges: true }, () => notifications++);
await new Promise(setImmediate);
assert.equal(notifications, 1);
const session = doc(sessions);
const batch = writeBatch(db);
batch.set(session, { title: 'Fixture verification', createdAt: fixture.serverTimestamp(), updatedAt: fixture.serverTimestamp() });
batch.set(doc(collection(session, 'messages')), { role: 'assistant', content: 'Hello', createdAt: fixture.serverTimestamp() });
await batch.commit();
await new Promise(setImmediate);
assert.equal(notifications, 2);
unsubscribe();
window.__fixture.failWrites = true;
await assert.rejects(setDoc(session, { title: 'Must not save' }));
assert.equal((await getDoc(session)).data().title, 'Fixture verification');
window.__fixture.failWrites = false;
await setDoc(doc(db, ...base, 'unrelated', 'change'), { value: 1 });
await new Promise(setImmediate);
assert.equal(notifications, 2);
const reloaded = await import('./firebase.js?reload-verification');
assert.equal((await reloaded.getDoc(session)).data().title, 'Fixture verification');
window.__fixture.reset({ empty: true });
assert.equal((await reloaded.getDocs(reloaded.collection(reloaded.db, ...base, 'habits'))).size, 0);
console.log('Fixture verification passed: seeded plans/data, date filtering, ordering/limit, timestamps, atomic notifications, unsubscribe, failed writes, persisted reload, empty reset.');
